import pdfplumber
import fitz  # PyMuPDF
import re
from pathlib import Path

# Patterns to identify sensitive information
PATTERNS = {
    'email': r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b',
    'arxiv_id': r'arXiv\.\d{4,5}\.\d{4,5}|arxiv\.org/abs/\d{4,5}\.\d{4,5}',
    'doi': r'(?:doi:|https://doi\.org/)[^\s)]+',
    'author_with_affiliation': r'[A-Z][a-z]+(?:\s+[A-Z][a-z]+)*\s*[♠♣⋆∗1-9]+',
}

class PDFRedactor:
    def __init__(self, pdf_path, output_path):
        self.pdf_path = pdf_path
        self.output_path = output_path
        self.sensitive_regions = []

    def extract_sensitive_info(self):
        """Extract locations of sensitive information"""
        with pdfplumber.open(self.pdf_path) as pdf:
            for page_num, page in enumerate(pdf.pages):
                text = page.extract_text()
                if not text:
                    continue

                # Check for author-identifying info on first few pages
                if page_num < 3:
                    # Look for author names with affiliations (institutions)
                    affiliation_pattern = r'(?:Duke|Carnegie|Cornell|Yale|MIT|Stanford|CMU|Adobe|Google|DeepMind|Berkeley|Princeton|Harvard|Georgia Institute|Renmin|KunShan|RUC|arXiv|Interspeech|ICML|NeurIPS|ICLR|ACL)'

                    # Find author blocks (typically on first page)
                    for match in re.finditer(affiliation_pattern, text, re.IGNORECASE):
                        self._mark_region_for_redaction(page_num, match.start(), match.end())

                    # Find arXiv IDs and DOIs
                    for pattern_name, pattern in PATTERNS.items():
                        for match in re.finditer(pattern, text):
                            self._mark_region_for_redaction(page_num, match.start(), match.end())

                    # Find email addresses
                    for match in re.finditer(PATTERNS['email'], text):
                        self._mark_region_for_redaction(page_num, match.start(), match.end())

                    # Find conference/venue information on first page
                    venue_pattern = r'(?:Interspeech|ICML|NeurIPS|ICLR|ACL|EMNLP|CVPR|ICCV|ECCV|IJCAI|AAAI)\s+\d{4}|\d{1,2}\s+(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{4}'
                    for match in re.finditer(venue_pattern, text, re.IGNORECASE):
                        self._mark_region_for_redaction(page_num, match.start(), match.end())

    def _mark_region_for_redaction(self, page_num, start_char, end_char):
        """Mark character position for redaction"""
        self.sensitive_regions.append({
            'page': page_num,
            'start': start_char,
            'end': end_char
        })

    def redact_pdf(self):
        """Create redacted PDF using PyMuPDF"""
        # Open with PyMuPDF for better redaction control
        doc = fitz.open(self.pdf_path)

        try:
            with pdfplumber.open(self.pdf_path) as pdf:
                # Process first 3 pages (where author info typically appears)
                for page_num in range(min(3, len(pdf.pages))):
                    page = pdf.pages[page_num]
                    text = page.extract_text()

                    if not text:
                        continue

                    # Get the PDF page
                    pdf_page = doc[page_num]

                    # Redact authors and affiliations (first page)
                    if page_num == 0:
                        # Author line pattern (names with superscripts)
                        author_match = re.search(
                            r'[A-Z][a-z]*\s+[A-Z][a-z]*[♠♣⋆∗].*?(?=\n\n|\nAbstract|\nAbstrak)',
                            text,
                            re.DOTALL
                        )
                        if author_match:
                            self._redact_text_region(pdf_page, text, author_match)

                        # Affiliation lines
                        affiliation_match = re.search(
                            r'[♠♣⋆∗].*?(?:University|Institute|Lab|Adobe|Google).*?(?:\n|$)',
                            text,
                            re.IGNORECASE | re.MULTILINE
                        )
                        if affiliation_match:
                            self._redact_text_region(pdf_page, text, affiliation_match)

                        # Email addresses
                        for email_match in re.finditer(PATTERNS['email'], text):
                            self._redact_text_region(pdf_page, text, email_match)

                        # arXiv IDs
                        for arxiv_match in re.finditer(PATTERNS['arxiv_id'], text):
                            self._redact_text_region(pdf_page, text, arxiv_match)

                        # Venue information
                        venue_match = re.search(
                            r'Interspeech|ICML|NeurIPS|ICLR|ACL|EMNLP|CVPR|ICCV|ECCV|\d{1,2}\s+(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{4}',
                            text,
                            re.IGNORECASE
                        )
                        if venue_match:
                            self._redact_text_region(pdf_page, text, venue_match)
        except Exception as e:
            print(f"Error processing with pdfplumber: {e}")

        # Save the redacted document
        doc.save(self.output_path)
        doc.close()
        print(f"Redacted PDF saved to: {self.output_path}")

    def _redact_text_region(self, page, text, match):
        """Redact a specific text region"""
        try:
            # Find text position in the page
            text_dict = page.get_text("dict")

            # Redact all instances of the matched text
            search_results = page.search_for(match.group())
            for rect in search_results:
                # Draw black rectangle over the text
                page.draw_rect(rect, color=None, fill=(0, 0, 0))
        except Exception as e:
            print(f"Error redacting region: {e}")

def redact_papers():
    """Redact all three papers"""
    papers = [
        ('/root/paper1.pdf', '/root/redacted/paper1.pdf'),
        ('/root/paper2.pdf', '/root/redacted/paper2.pdf'),
        ('/root/paper3.pdf', '/root/redacted/paper3.pdf'),
    ]

    for input_path, output_path in papers:
        print(f"\nProcessing: {input_path}")
        try:
            redactor = PDFRedactor(input_path, output_path)
            redactor.extract_sensitive_info()
            redactor.redact_pdf()
        except Exception as e:
            print(f"Error redacting {input_path}: {e}")
            import traceback
            traceback.print_exc()

if __name__ == '__main__':
    redact_papers()

